  const shapes = new Map(rows.map(row => [row[0], row[4]]));
  const items = previous.items.concat(rows.map(([id, label, category, keywords]) => ({id, label, category, keywords})));
  const cache = new Map();
  function path(id) {
    if (!shapes.has(id)) return previous.path(id);
    if (!cache.has(id)) {
      const outline = shapes.get(id);
      const segments = Array.from(outline.matchAll(/([MLCZ])([^MLCZ]*)/g), ([, op, coords]) =>
        coords ? [op, ...coords.split(' ').map(Number)] : [op]);
      cache.set(id, segments);
    }
    return cache.get(id);
  }
  window.BenchCatalog = Object.freeze({items, path});
